a) static boolean isFarmIdValid(String farmID) {
 return farmID.matches("[DIC]-\\d{3}-\\d{5}") && Integer.parseInt(farmID.split("-")[2]) <= 49999;
}

b) static String getRegion(String farmID) {
 if (isFarmIdValid(farmID)) {
 return farmID.split("-")[1];
 }
 return "unknown";
}

